-- Four newly verified products only. Existing products/history are never rewritten.
begin;
set local statement_timeout='20s';
set local lock_timeout='5s';
select pg_advisory_xact_lock(1617125,13);
create temporary table batch_input as select * from jsonb_to_recordset($data$[{"shop": "QuGifts", "listing_id": "1843847088", "source_url": "https://www.etsy.com/listing/1843847088/handmade-capiz-shell-wall-hanging-boho", "category": "Coastal Home Decor", "board_id": "675399344056772225", "new_title": "Capiz Shell Wall Hanging on a Natural Branch", "body": "Translucent white shell discs cascade from a natural wooden branch in this coastal wall hanging from QuGifts. Natural shell markings vary. See the original Etsy listing for sizes and details.", "image_url": "https://i.etsystatic.com/38006525/r/il/cb453d/6757669660/il_1588xN.6757669660_bj9g.jpg", "checked_at": "2026-10-13T05:15:48.219Z", "facebook_draft": "Looking for a coastal wall accent? This QuGifts hanging combines a natural branch with cascading shell discs. Explore sizes and details on Etsy. https://www.etsy.com/listing/1843847088/handmade-capiz-shell-wall-hanging-boho"}, {"shop": "QuGifts", "listing_id": "1858605625", "source_url": "https://www.etsy.com/listing/1858605625/handmade-capiz-shell-wind-chime-boho", "category": "Coastal Home Decor", "board_id": "675399344056772225", "new_title": "White Capiz Shell Wind Chime with Rattan Top", "body": "A circular rattan top supports strands of translucent white capiz shells in this QuGifts wind chime. A light, textured accent for coastal interiors. Visit the original Etsy listing for details.", "image_url": "https://i.etsystatic.com/38006525/r/il/f7b40a/6805615303/il_1588xN.6805615303_irdp.jpg", "checked_at": "2026-10-13T05:16:21.439Z", "facebook_draft": "Shell discs and a round rattan top bring a coastal touch to this QuGifts wind chime. Take a closer look at the original listing on Etsy. https://www.etsy.com/listing/1858605625/handmade-capiz-shell-wind-chime-boho"}, {"shop": "QuGifts", "listing_id": "4338894105", "source_url": "https://www.etsy.com/listing/4338894105/boho-cowrie-shell-wall-mirror-handmade", "category": "Coastal Home Decor", "board_id": "675399344056772225", "new_title": "Round Cowrie Shell Wall Mirror", "body": "Rows of cream-colored cowrie shells frame a round mirror, finished with a natural rope edge. From QuGifts, for coastal and boho wall decor. See dimensions and details on Etsy.", "image_url": "https://i.etsystatic.com/38006525/r/il/0cbdd6/7086351405/il_1588xN.7086351405_anut.jpg", "checked_at": "2026-10-13T05:16:31.247Z", "facebook_draft": "A round mirror surrounded by rows of cowrie shells: a textured wall accent from QuGifts. Check the original Etsy listing for dimensions and details. https://www.etsy.com/listing/4338894105/boho-cowrie-shell-wall-mirror-handmade"}, {"shop": "QuGifts", "listing_id": "4353446272", "source_url": "https://www.etsy.com/listing/4353446272/handwoven-seashell-ornament-coastal-boho", "category": "Coastal Home Decor", "board_id": "675399344056772225", "new_title": "Seashell and Jute Rope Table Ornament", "body": "Clusters of natural shells and a loop of jute rope form this QuGifts table ornament. Style it on a shelf or decorative tray; shell colors and shapes vary. View available styles on Etsy.", "image_url": "https://i.etsystatic.com/38006525/r/il/ed58c4/7142161014/il_1588xN.7142161014_4pge.jpg", "checked_at": "2026-10-13T05:16:39.534Z", "facebook_draft": "Add shell texture to a shelf or tabletop with this QuGifts seashell ornament. The listing offers different shell styles; browse the original Etsy page for details. https://www.etsy.com/listing/4353446272/handwoven-seashell-ornament-coastal-boho"}]$data$::jsonb) x(shop text,listing_id text,source_url text,category text,board_id text,new_title text,body text,image_url text,checked_at timestamptz,facebook_draft text);
do $$ begin
 if not exists(select 1 from pinterest_publish_settings where singleton and enabled and access_tier='standard') then raise exception 'Enabled Standard required'; end if;
 if exists(select 1 from batch_input where checked_at<now()-interval '24 hours' or checked_at>now()) then raise exception 'Verification expired'; end if;
 if (select count(*) from batch_input x join shops s on s.shop_name=x.shop and s.status='active' join shop_social_accounts m on m.shop_id=s.id and m.active and m.platform='pinterest' join social_accounts a on a.id=m.social_account_id and a.handle='cindyzhang62' and a.active and a.platform='pinterest' join pinterest_oauth_credentials cr on cr.social_account_id=a.id and lower(cr.pinterest_username)='cindyzhang62')<>4 then raise exception 'P4 routing or authorization changed'; end if;
end $$;
-- Report prior records before inserting; only genuinely new products enter this batch.
select json_build_object('preexisting_listing',p.etsy_listing_id,'history_count',(select count(*) from publish_history h where h.product_id=p.id)) from products p join batch_input x on x.listing_id=p.etsy_listing_id;
create temporary table new_products(id uuid,shop_id uuid,etsy_listing_id text);
with ins as (
 insert into products(shop_id,etsy_listing_id,etsy_url,title,category,listing_status,primary_image_url,original_image_urls,source_payload,source_discovered_at,last_seen_at)
 select s.id,x.listing_id,x.source_url,x.new_title,x.category,'active',x.image_url,jsonb_build_array(x.image_url),jsonb_build_object('verified_at',x.checked_at,'source',x.source_url,'image_verified',true,'batch','p4-20261013-2'),x.checked_at,x.checked_at from batch_input x join shops s on s.shop_name=x.shop
 where not exists(select 1 from products p where p.etsy_listing_id=x.listing_id)
 on conflict(shop_id,etsy_listing_id) do nothing returning id,shop_id,etsy_listing_id
) insert into new_products select * from ins;
insert into content_variants(shop_id,product_id,platform,creative_id,image_url,title,body,destination_url,board_or_category,content_type,status)
select p.shop_id,p.id,'pinterest','verified-original-20261013',x.image_url,x.new_title,x.body,x.source_url,x.category,'product','ready' from new_products p join batch_input x on x.listing_id=p.etsy_listing_id;
insert into content_variants(shop_id,product_id,platform,creative_id,image_url,title,body,destination_url,board_or_category,content_type,status)
select p.shop_id,p.id,'facebook','verified-original-20261013',x.image_url,x.new_title,x.facebook_draft,x.source_url,x.category,'product','draft' from new_products p join batch_input x on x.listing_id=p.etsy_listing_id;
insert into publish_queue(shop_id,product_id,content_variant_id,platform,social_account_id,status)
select p.shop_id,p.id,cv.id,'pinterest',a.id,'ready' from new_products p join content_variants cv on cv.product_id=p.id and cv.platform='pinterest' join social_accounts a on a.handle='cindyzhang62' and a.platform='pinterest';
insert into pinterest_publish_reviews(queue_id,board_id,snapshot,listing_checked_at,source_url)
select q.id,x.board_id,pinterest_publish_snapshot(q.id),x.checked_at,x.source_url from new_products p join batch_input x on x.listing_id=p.etsy_listing_id join publish_queue q on q.product_id=p.id and q.platform='pinterest';
select json_build_object('listing_id',p.etsy_listing_id,'queue_id',q.id,'status',q.status,'board_id',r.board_id,'snapshot_matches',r.snapshot=pinterest_publish_snapshot(q.id)) from products p join batch_input x on x.listing_id=p.etsy_listing_id join publish_queue q on q.product_id=p.id and q.platform='pinterest' join pinterest_publish_reviews r on r.queue_id=q.id;
commit;
